+        keys.set(keyOffset, key1);
+        keys.set(keyOffset + 1, key2);
+        keys.set(keyOffset + 2, key3);
+    }
+
+    private void reset(int key1, int key2, int key3, long id) {
+        long index = slot(hash(key1, key2, key3), mask);
