+    }
+
+    @Override
+    public void close() {
+        Releasables.close(keys, super::close);
+    }
+
+    static long hash(long key1, long key2, long key3) {
+        return 31L * (31L * BitMixer.mix(key1) + BitMixer.mix(key2)) + BitMixer.mix(key3);
+    }
